:root {
  --bg: #1b1b2f;
  --card: #2e2e4a;
  --text: #e8e8f0;
  --accent: #ffcc00;
  --accent-dark: #cc9900;
  --danger: #ff5c5c;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  color: var(--text);
  font-family: 'Courier New', Courier, monospace;
  font-size: 18px;
  padding: 16px;
}
.card {
  background: var(--card);
  border: 4px solid var(--accent);
  box-shadow: 8px 8px 0 #000;
  padding: 24px;
  width: 100%;
  max-width: 480px;
}
h1 {
  margin: 0 0 16px;
  font-size: 28px;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--accent);
}
.counts {
  display: flex;
  gap: 24px;
  margin-bottom: 16px;
  font-size: 16px;
}
.counts strong { color: var(--accent); }
.add-row {
  display: flex;
  gap: 8px;
  margin-bottom: 16px;
}
input[type="text"] {
  flex: 1;
  min-width: 0;
  padding: 10px;
  font: inherit;
  background: #12121f;
  color: var(--text);
  border: 3px solid var(--accent);
  outline: none;
}
input[type="text"]:focus { border-color: #fff; }
button {
  font: inherit;
  cursor: pointer;
  background: var(--accent);
  color: #1b1b2f;
  border: 3px solid #000;
  padding: 10px 16px;
  box-shadow: 3px 3px 0 #000;
  transition: transform 0.05s, box-shadow 0.05s;
}
button:hover { background: var(--accent-dark); }
button:focus-visible { outline: 3px solid #fff; outline-offset: 2px; }
button:active { transform: translate(3px, 3px); box-shadow: none; }
.todo-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.todo-list li {
  display: flex;
  align-items: center;
  gap: 8px;
  background: #12121f;
  padding: 8px;
  border: 2px solid #444;
}
.todo-list input[type="checkbox"] {
  width: 20px;
  height: 20px;
  accent-color: var(--accent);
  cursor: pointer;
}
.todo-list span {
  flex: 1;
  word-break: break-word;
}
.todo-list li.done span { text-decoration: line-through; opacity: 0.6; }
.todo-list button {
  background: var(--danger);
  color: #fff;
  padding: 4px 10px;
  font-size: 16px;
}
.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}
@media (max-width: 400px) {
  .card { padding: 16px; }
  .counts { flex-direction: column; gap: 4px; }
}

const input = document.getElementById('todo-input');
const addBtn = document.getElementById('todo-add');
const form = document.getElementById('todo-form');
const list = document.getElementById('todo-list');
const totalEl = document.getElementById('todo-total');
const remainingEl = document.getElementById('remaining');

let tasks = [];
let nextId = 1;

function updateCounts() {
  totalEl.textContent = String(tasks.length);
  const remaining = tasks.filter(t => !t.done).length;
  remainingEl.textContent = String(remaining);
}

function render() {
  list.innerHTML = '';
  tasks.forEach(task => {
    const li = document.createElement('li');
    if (task.done) li.classList.add('done');

    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.id = `todo-check-${task.id}`;
    checkbox.checked = task.done;
    checkbox.setAttribute('aria-label', `Mark ${task.text} as complete`);
    checkbox.addEventListener('change', () => {
      task.done = checkbox.checked;
      li.classList.toggle('done', task.done);
      updateCounts();
    });

    const span = document.createElement('span');
    span.id = `todo-text-${task.id}`;
    span.textContent = task.text;

    const del = document.createElement('button');
    del.type = 'button';
    del.id = `todo-delete-${task.id}`;
    del.textContent = 'Delete';
    del.setAttribute('aria-label', `Delete ${task.text}`);
    del.addEventListener('click', () => {
      tasks = tasks.filter(t => t.id !== task.id);
      render();
      updateCounts();
    });

    li.appendChild(checkbox);
    li.appendChild(span);
    li.appendChild(del);
    list.appendChild(li);
  });
}

function addTask() {
  const text = input.value.trim();
  if (!text) return;
  tasks.push({ id: nextId++, text, done: false });
  input.value = '';
  render();
  updateCounts();
  input.focus();
}

form.addEventListener('submit', (e) => {
  e.preventDefault();
  addTask();
});

updateCounts();
